style.css:
@-moz-document domain("walmart.com") {
@media screen and (forced-colors: none) {
    /* Classic selector syntax; literal colors avoid CSS-variable parsing dependencies. */

    html,
    body,
    #__next,
    [data-testid="layout-container"],
    [data-testid="main-content-container"],
    [data-testid="maincontent"],
    #maincontent,
    main {
      background-color: #0b1220 !important;
      color: #e8eef7 !important;
    }

    html {
      color-scheme: dark !important;
      scrollbar-color: #31445c #0b1220 !important;
    }

    /* Shared surfaces. Single-argument :not() is CSS3 syntax; no selector-list functions. */

    .bg-white:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-white-90:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-white-80:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-near-white:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-light-gray:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-light-grey:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-washed-blue:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-washed-primary:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-washed-cyan:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-washed-yellow:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-washed-green:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    .bg-washed-red:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper) {
      background-color: #121e30 !important;
    }

    .black,
    .near-black,
    .dark-gray,
    .dark-grey,
    .navy,
    .dark-blue,
    h1,
    h2,
    h3,
    h4,
    h5,
    h6,
    label,
    legend {
      color: #e8eef7 !important;
    }

    .gray,
    .grey,
    .mid-gray,
    .mid-grey,
    .silver,
    .light-silver,
    .dark-gray-70,
    .black-60,
    .black-70,
    small,
    del,
    s {
      color: #a8b7cc !important;
    }

    a {
      color: #6cb6ff !important;
    }

    a:hover {
      color: #ffd35a !important;
    }

    .b--near-white,
    .b--light-gray,
    .b--light-grey,
    .b--gray,
    .b--gray-30,
    .b--black-10,
    .b--black-20,
    .b--white-90,
    .b--cyan,
    .b--primary,
    hr {
      border-color: #31445c !important;
    }

    /* Header, secondary navigation, and fulfillment banner. */

    [data-testid="global-header"],
    [data-testid="responsiveHeader"],
    [data-testid="hearder-navigation"],
    [data-testid="sub-nav-links-container"],
    .header-navigation,
    header.bg-primary,
    header.bg-dark-primary,
    header .bg-secondary,
    [data-testid="global-header"] .bg-secondary {
      background-color: #121e30 !important;
      color: #e8eef7 !important;
      border-color: #31445c !important;
    }

    .secondary-nav-flyout-trigger,
    .desktop-header-trigger,
    .desktop-header-flyout-link,
    .cart-button-redesigned,
    [data-testid="global-header"] a,
    [data-testid="responsiveHeader"] a {
      color: #e8eef7 !important;
      border-color: #31445c !important;
    }

    .secondary-nav-flyout-trigger {
      background-color: #19283e !important;
    }

    .secondary-nav-flyout-trigger:hover,
    .desktop-header-trigger:hover,
    .desktop-header-flyout-link:hover,
    .cart-button-redesigned:hover {
      background-color: #233854 !important;
      color: #ffd35a !important;
    }

    [data-testid="global-intent-center"],
    [data-testid="global-intent-center-banner"],
    [data-automation-id="fulfillment-banner"] {
      background-color: #19283e !important;
      color: #e8eef7 !important;
    }

    /* Flyouts, autocomplete, dialogs, menus, and drawers. */

    [data-testid="account-flyout"],
    [data-testid="my-items-flyout"],
    [data-testid="departments-flyout"],
    [data-testid="services-flyout"],
    #typeahead-listbox,
    [role="listbox"],
    [role="menu"],
    [role="dialog"],
    [aria-modal="true"],
    dialog,
    [role="tooltip"] {
      background-color: #121e30 !important;
      color: #e8eef7 !important;
      border-color: #31445c !important;
      box-shadow: 0 12px 36px rgba(0, 0, 0, 0.4) !important;
    }

    [role="option"]:hover,
    [role="menuitem"]:hover,
    [role="option"][aria-selected="true"],
    [id^="typeahead-suggestion-"]:hover {
      background-color: #233854 !important;
      color: #e8eef7 !important;
    }

    dialog::backdrop {
      background-color: rgba(0, 0, 0, 0.65) !important;
    }

    /* Ordinary controls. Repeated selector lists replace :is() and :where(). */

    button:not([role="radio"]):not([data-testid*="swatch"]),
    [role="button"]:not([data-testid*="swatch"]),
    input[type="button"],
    input[type="submit"] {
      background-color: #19283e !important;
      color: #e8eef7 !important;
      border-color: #31445c !important;
    }

    button.bg-transparent:not([role="radio"]):not([data-testid*="swatch"]),
    [role="button"].bg-transparent:not([data-testid*="swatch"]) {
      background-color: transparent !important;
    }

    button:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    [role="button"]:not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    input[type="button"]:hover:not(:disabled):not([aria-disabled="true"]),
    input[type="submit"]:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: #233854 !important;
      color: #e8eef7 !important;
    }

    [data-automation-id="add-to-cart"]:not([role="radio"]):not([data-testid*="swatch"]),
    [data-testid="sign-in"]:not([role="radio"]):not([data-testid*="swatch"]),
    [data-testid="search-form"] button[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]),
    button.search-icon-redesigned-v2:not([role="radio"]):not([data-testid*="swatch"]),
    button.bg-primary:not([role="radio"]):not([data-testid*="swatch"]),
    a.bg-primary:not([role="radio"]):not([data-testid*="swatch"]),
    [role="button"].bg-primary:not([role="radio"]):not([data-testid*="swatch"]),
    button[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]),
    input[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]),
    [role="tab"][aria-selected="true"]:not([role="radio"]):not([data-testid*="swatch"]),
    button[aria-pressed="true"]:not([role="radio"]):not([data-testid*="swatch"]) {
      background-color: #6cb6ff !important;
      color: #0b1220 !important;
      border-color: #6cb6ff !important;
    }

    [data-automation-id="add-to-cart"]:not([role="radio"]):not([data-testid*="swatch"]) span,
    [data-automation-id="add-to-cart"]:not([role="radio"]):not([data-testid*="swatch"]) i,
    [data-testid="sign-in"]:not([role="radio"]):not([data-testid*="swatch"]) span,
    [data-testid="sign-in"]:not([role="radio"]):not([data-testid*="swatch"]) i,
    [data-testid="search-form"] button[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]) span,
    [data-testid="search-form"] button[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]) i,
    button.search-icon-redesigned-v2:not([role="radio"]):not([data-testid*="swatch"]) span,
    button.search-icon-redesigned-v2:not([role="radio"]):not([data-testid*="swatch"]) i,
    button.bg-primary:not([role="radio"]):not([data-testid*="swatch"]) span,
    button.bg-primary:not([role="radio"]):not([data-testid*="swatch"]) i,
    a.bg-primary:not([role="radio"]):not([data-testid*="swatch"]) span,
    a.bg-primary:not([role="radio"]):not([data-testid*="swatch"]) i,
    [role="button"].bg-primary:not([role="radio"]):not([data-testid*="swatch"]) span,
    [role="button"].bg-primary:not([role="radio"]):not([data-testid*="swatch"]) i,
    button[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]) span,
    button[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]) i,
    input[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]) span,
    input[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]) i,
    [role="tab"][aria-selected="true"]:not([role="radio"]):not([data-testid*="swatch"]) span,
    [role="tab"][aria-selected="true"]:not([role="radio"]):not([data-testid*="swatch"]) i,
    button[aria-pressed="true"]:not([role="radio"]):not([data-testid*="swatch"]) span,
    button[aria-pressed="true"]:not([role="radio"]):not([data-testid*="swatch"]) i {
      color: inherit !important;
    }

    [data-automation-id="add-to-cart"]:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    [data-testid="sign-in"]:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    [data-testid="search-form"] button[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    button.search-icon-redesigned-v2:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    button.bg-primary:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    a.bg-primary:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    [role="button"].bg-primary:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    button[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    input[type="submit"]:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: #ffd35a !important;
      color: #0b1220 !important;
      border-color: #ffd35a !important;
    }

    button:disabled,
    input:disabled,
    select:disabled,
    textarea:disabled,
    [role="button"][aria-disabled="true"] {
      opacity: 0.55 !important;
    }

    /* Search and standard form fields; preserve checkbox, radio, and color inputs. */

    input:not([type]),
    input[type="text"],
    input[type="search"],
    input[type="email"],
    input[type="password"],
    input[type="tel"],
    input[type="number"],
    input[type="url"],
    input[type="date"],
    input[type="time"],
    textarea,
    select,
    .search-bar,
    .search-input-field-v2,
    .search-bar-redesigned-v2 {
      background-color: #0b1220 !important;
      color: #e8eef7 !important;
      border-color: #31445c !important;
      caret-color: #6cb6ff !important;
    }

    [data-automation-id="header-input-search"] {
      box-shadow: inset 0 0 0 1px #0071ce !important;
    }

    input::placeholder,
    textarea::placeholder {
      color: #a8b7cc !important;
      opacity: 1 !important;
    }

    option,
    optgroup {
      background-color: #121e30 !important;
      color: #e8eef7 !important;
    }

    input[type="checkbox"],
    input[type="radio"],
    input[type="range"] {
      accent-color: #6cb6ff !important;
    }

    input[aria-invalid="true"],
    select[aria-invalid="true"],
    textarea[aria-invalid="true"] {
      border-color: #ff9f9f !important;
    }

    /* Results, prices, filter rails, and sticky filter rows. */

    [data-testid="products"],
    [data-testid="item-stack"],
    [data-testid="lhn"],
    [data-testid="lhn-scroll-container"],
    [data-testid="fixed-wrapper"],
    [data-testid="fixed-wrapper-placeholder"] {
      background-color: #0b1220 !important;
      color: #e8eef7 !important;
      border-color: #31445c !important;
    }

    [data-automation-id="product-title"],
    [data-automation-id="product-price"],
    [data-testid="unified-global-product-price"],
    [data-testid="ugpp-main-price"],
    [data-testid="ugpp-range-price"] {
      color: #e8eef7 !important;
    }

    [data-testid="ugpp-was-price"] {
      color: #a8b7cc !important;
    }

    [data-testid="ugpp-reduced-price"],
    [data-testid="ugpp-reduced-price-display"],
    .green,
    .dark-green {
      color: #86dfb0 !important;
    }

    .red,
    .dark-red {
      color: #ff9f9f !important;
    }

    .gold,
    .yellow,
    .orange,
    [data-testid="star-filled"],
    [data-testid="star-halfFilled"] {
      color: #ffd35a !important;
    }

    [data-automation-id="page-number"][aria-current="page"]:not([role="radio"]):not([data-testid*="swatch"]),
    [aria-current="page"][role="button"]:not([role="radio"]):not([data-testid*="swatch"]) {
      background-color: #6cb6ff !important;
      color: #0b1220 !important;
      border-color: #6cb6ff !important;
    }

    /* Footer, tables, and the assistant launcher surface. */

    footer,
    [data-testid="responsive-footer-list"],
    .sparky-fab-wrapper,
    table,
    th,
    td {
      background-color: #121e30 !important;
      color: #e8eef7 !important;
      border-color: #31445c !important;
    }

    /* Readable captions and controls on photographic promotion tiles. */

    .card-wrapper {
      color: #2e2f32 !important;
    }

    .card-wrapper h1,
    .card-wrapper h2,
    .card-wrapper h3,
    .card-wrapper h4,
    .card-wrapper h5,
    .card-wrapper h6 {
      color: inherit !important;
    }

    .card-wrapper .black,
    .card-wrapper .near-black {
      color: #000000 !important;
    }

    .card-wrapper .dark-gray,
    .card-wrapper .dark-grey {
      color: #2e2f32 !important;
    }

    .card-wrapper .navy,
    .card-wrapper .dark-blue {
      color: #001e60 !important;
    }

    .card-wrapper .gray,
    .card-wrapper .grey,
    .card-wrapper .mid-gray,
    .card-wrapper .mid-grey,
    .card-wrapper small {
      color: #46474a !important;
    }

    .card-wrapper .white {
      color: #ffffff !important;
    }

    .card-wrapper a,
    .card-wrapper a:hover {
      color: inherit !important;
    }

    .card-wrapper .bg-white:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    [data-testid*="swatch"] .bg-white:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper) {
      background-color: #ffffff !important;
    }

    .card-wrapper .bg-near-white:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper),
    [data-testid*="swatch"] .bg-near-white:not(img):not(picture):not(svg):not(video):not(canvas):not(button):not(a):not(input):not([role="button"]):not([role="radio"]):not([data-testid*="swatch"]):not(.card-wrapper) {
      background-color: #f5f5f5 !important;
    }

    .card-wrapper button:not([role="radio"]):not([data-testid*="swatch"]),
    .card-wrapper [role="button"]:not([data-testid*="swatch"]),
    .card-wrapper input[type="button"],
    .card-wrapper input[type="submit"] {
      background-color: #ffffff !important;
      color: #001e60 !important;
      border-color: #001e60 !important;
    }

    .card-wrapper button.bg-transparent:not([role="radio"]):not([data-testid*="swatch"]),
    .card-wrapper [role="button"].bg-transparent:not([role="radio"]):not([data-testid*="swatch"]) {
      background-color: transparent !important;
      color: inherit !important;
    }

    .card-wrapper button:not([role="radio"]):not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    .card-wrapper [role="button"]:not([data-testid*="swatch"]):hover:not(:disabled):not([aria-disabled="true"]),
    .card-wrapper input[type="button"]:hover:not(:disabled):not([aria-disabled="true"]),
    .card-wrapper input[type="submit"]:hover:not(:disabled):not([aria-disabled="true"]) {
      background-color: #f5f5f5 !important;
      color: #001e60 !important;
    }

    /* Classic :focus keeps keyboard focus visible without functional selectors. */

    a:focus,
    button:focus,
    input:focus,
    select:focus,
    textarea:focus,
    summary:focus,
    [tabindex]:focus {
      outline: 2px solid #ffd35a !important;
      outline-offset: 3px !important;
    }

    ::selection {
      background-color: #6cb6ff !important;
      color: #0b1220 !important;
    }

    ::-webkit-scrollbar {
      width: 12px !important;
      height: 12px !important;
    }

    ::-webkit-scrollbar-track {
      background-color: #0b1220 !important;
    }

    ::-webkit-scrollbar-thumb {
      background-color: #31445c !important;
      border: 3px solid #0b1220 !important;
      border-radius: 10px !important;
    }

    /* No image filters, blanket SVG fills, external resources, or layout changes. */
  }
}
